#!/usr/bin/env bash
#
# Generates printers.env from printers.list by fetching each printer's
# certificate fingerprint. Needs network access to the printers.
#
# usage: ./build-printers-env.sh [printers.list] [printers.env]

set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
list="${1:-$here/printers.list}"
out="${2:-$here/printers.env}"

if [[ ! -f "$list" ]]; then
    echo "$0: no such list: $list" >&2
    exit 1
fi

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT

cat > "$tmp" <<'EOF'
# GENERATED by build-printers-env.sh from printers.list - do not edit by hand.
# Hand-maintained mediamtx settings live in mediamtx.env instead.
#
# mediamtx path overrides, loaded by the mediamtx service via env_file.
# mediamtx loads these AFTER mediamtx.yml, so they win over the stock file.
#
# Path name = the key in bambu.printers.<id>. BambuPrinterImpl builds the live
# view url as bambu.live-view-url + id, so it is also the mediamtx path name.
# It must be a single word: mediamtx takes only the first _-delimited segment
# as the map key, so a name with an underscore is silently truncated.
#
# SOURCEFINGERPRINT is mandatory because the printers use self-signed certs;
# an empty value makes mediamtx fall back to CA verification and fail.

EOF

count=0
while read -r name ip code _; do
    [[ -z "${name:-}" || "$name" == \#* ]] && continue

    printf 'fetching %s from %s ... ' "$name" "$ip" >&2
    fp="$("$here/extract-fingerprint.sh" "$ip")"
    printf '%s\n' "$fp" >&2

    {
        printf 'MTX_PATHS_%s_SOURCE=rtsps://bblp:%s@%s:322/streaming/live/1\n' "${name^^}" "$code" "$ip"
        printf 'MTX_PATHS_%s_SOURCEFINGERPRINT=%s\n\n' "${name^^}" "$fp"
    } >> "$tmp"

    count=$((count + 1))
done < "$list"

if [[ "$count" -eq 0 ]]; then
    echo "$0: no printers found in $list" >&2
    exit 1
fi

mv "$tmp" "$out"
trap - EXIT

printf '\nwrote %s (%d printers)\n' "$out" "$count" >&2
